code.smoke_test_yaml:
experiments:
  # --------------------------------------------------------------------------------
  # Smoke test – lightweight versions of ALL variations (epochs reduced to 1-2,
  # dataset samples drastically down-sampled).  The goal is pipeline integrity.
  # --------------------------------------------------------------------------------
  - run_id: cartpole_random-search
    description: Random search surrogate classification (CartPole) – smoke
    dataset:
      name: cartpole-v0
      num_samples: 500
    model:
      name: baseline_mlp
      hidden_units: [32, 32]
    training:
      epochs: 1
      batch_size: 64
      learning_rate: 0.001
      resume: false
  - run_id: cartpole_BOIL-linear
    description: BOIL linear surrogate – smoke
    dataset: {name: cartpole-v0, num_samples: 500}
    model: {name: baseline_mlp, hidden_units: [32, 32]}
    training: {epochs: 1, batch_size: 64, learning_rate: 0.001}
  - run_id: cartpole_COCO-BOIL-M1-only
    description: COCO-BOIL M1 only – smoke
    dataset: {name: cartpole-v0, num_samples: 500}
    model: {name: baseline_mlp, hidden_units: [32, 32]}
    training: {epochs: 1, batch_size: 64, learning_rate: 0.001}
  - run_id: cartpole_COCO-BOIL-M2-only
    description: COCO-BOIL M2 only – smoke
    dataset: {name: cartpole-v0, num_samples: 500}
    model: {name: baseline_mlp, hidden_units: [32, 32]}
    training: {epochs: 1, batch_size: 64, learning_rate: 0.001}
  - run_id: cartpole_COCO-BOIL-full
    description: COCO-BOIL full – smoke
    dataset: {name: cartpole-v0, num_samples: 500}
    model: {name: baseline_mlp, hidden_units: [32, 32]}
    training: {epochs: 1, batch_size: 64, learning_rate: 0.001}

  # Vision dataset (SVHN) ------------------------------------------------------------
  - run_id: svhn_random-search
    description: Random search – SVHN – smoke
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 1, batch_size: 32, learning_rate: 0.001}
  - run_id: svhn_BOIL-linear
    description: BOIL linear – SVHN – smoke
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 1, batch_size: 32, learning_rate: 0.001}
  - run_id: svhn_COCO-BOIL-M1-only
    description: COCO-BOIL M1 only – SVHN – smoke
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 1, batch_size: 32, learning_rate: 0.001}
  - run_id: svhn_COCO-BOIL-M2-only
    description: COCO-BOIL M2 only – SVHN – smoke
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 1, batch_size: 32, learning_rate: 0.001}
  - run_id: svhn_COCO-BOIL-full
    description: COCO-BOIL full – SVHN – smoke
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 1, batch_size: 32, learning_rate: 0.001}

code.full_experiment_yaml:
experiments:
  # --------------------------------------------------------------------------------
  # 1) CartPole-v0 RL surrogate classification (DDQN baseline) ----------------------
  # --------------------------------------------------------------------------------
  - run_id: cartpole_random-search
    description: Random search baseline for CartPole hyper-params.
    dataset: {name: cartpole-v0, num_samples: 5000}
    model: {name: baseline_mlp, hidden_units: [128, 128], dropout: 0.0}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.0005}
  - run_id: cartpole_BOIL-linear
    description: Original BOIL with linear cost surrogate – CartPole.
    dataset: {name: cartpole-v0, num_samples: 5000}
    model: {name: baseline_mlp, hidden_units: [128, 128]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.0005}
  - run_id: cartpole_COCO-BOIL-M1-only
    description: COCO-BOIL ablation (M1 only) – CartPole.
    dataset: {name: cartpole-v0, num_samples: 5000}
    model: {name: baseline_mlp, hidden_units: [128, 128]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.0005}
  - run_id: cartpole_COCO-BOIL-M2-only
    description: COCO-BOIL ablation (M2 only) – CartPole.
    dataset: {name: cartpole-v0, num_samples: 5000}
    model: {name: baseline_mlp, hidden_units: [128, 128]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.0005}
  - run_id: cartpole_COCO-BOIL-full
    description: COCO-BOIL full – CartPole.
    dataset: {name: cartpole-v0, num_samples: 5000}
    model: {name: baseline_mlp, hidden_units: [128, 128]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.0005}

  # --------------------------------------------------------------------------------
  # 2) SVHN vision dataset (light-CNN baseline) -------------------------------------
  # --------------------------------------------------------------------------------
  - run_id: svhn_random-search
    description: Random search on SVHN (light CNN baseline).
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 20, batch_size: 128, learning_rate: 0.001}
  - run_id: svhn_BOIL-linear
    description: Original BOIL with linear cost surrogate – SVHN.
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 20, batch_size: 128, learning_rate: 0.001}
  - run_id: svhn_COCO-BOIL-M1-only
    description: COCO-BOIL ablation (M1 only) – SVHN.
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 20, batch_size: 128, learning_rate: 0.001}
  - run_id: svhn_COCO-BOIL-M2-only
    description: COCO-BOIL ablation (M2 only) – SVHN.
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 20, batch_size: 128, learning_rate: 0.001}
  - run_id: svhn_COCO-BOIL-full
    description: COCO-BOIL full – SVHN.
    dataset: {name: svhn, val_fraction: 0.1}
    model: {name: light_cnn, dropout: 0.1}
    training: {epochs: 20, batch_size: 128, learning_rate: 0.001}

  # --------------------------------------------------------------------------------
  # 3) CIFAR-10 vision dataset (ResNet-18 baseline) ---------------------------------
  # --------------------------------------------------------------------------------
  - run_id: cifar_random-search
    description: Random search baseline – CIFAR-10 with ResNet-18.
    dataset: {name: cifar10, val_fraction: 0.1}
    model: {name: resnet18, pretrained: false}
    training: {epochs: 30, batch_size: 256, learning_rate: 0.01}
  - run_id: cifar_BOIL-linear
    description: BOIL linear cost surrogate – CIFAR-10.
    dataset: {name: cifar10, val_fraction: 0.1}
    model: {name: resnet18, pretrained: false}
    training: {epochs: 30, batch_size: 256, learning_rate: 0.01}
  - run_id: cifar_COCO-BOIL-M1-only
    description: COCO-BOIL ablation (M1 only) – CIFAR-10.
    dataset: {name: cifar10, val_fraction: 0.1}
    model: {name: resnet18, pretrained: false}
    training: {epochs: 30, batch_size: 256, learning_rate: 0.01}
  - run_id: cifar_COCO-BOIL-M2-only
    description: COCO-BOIL ablation (M2 only) – CIFAR-10.
    dataset: {name: cifar10, val_fraction: 0.1}
    model: {name: resnet18, pretrained: false}
    training: {epochs: 30, batch_size: 256, learning_rate: 0.01}
  - run_id: cifar_COCO-BOIL-full
    description: COCO-BOIL full – CIFAR-10.
    dataset: {name: cifar10, val_fraction: 0.1}
    model: {name: resnet18, pretrained: false}
    training: {epochs: 30, batch_size: 256, learning_rate: 0.01}

  # --------------------------------------------------------------------------------
  # 4) InvertedPendulum & 5) Reacher are specified for completeness, but kept small
  #    to limit resource usage.  They reuse the MLP surrogate classification.
  # --------------------------------------------------------------------------------
  - run_id: invertedpendulum_random-search
    description: Random search – InvertedPendulum surrogate.
    dataset: {name: invertedpendulum-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: invertedpendulum_BOIL-linear
    description: BOIL linear – InvertedPendulum.
    dataset: {name: invertedpendulum-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: invertedpendulum_COCO-BOIL-M1-only
    description: COCO-BOIL M1 only – InvertedPendulum.
    dataset: {name: invertedpendulum-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: invertedpendulum_COCO-BOIL-M2-only
    description: COCO-BOIL M2 only – InvertedPendulum.
    dataset: {name: invertedpendulum-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: invertedpendulum_COCO-BOIL-full
    description: COCO-BOIL full – InvertedPendulum.
    dataset: {name: invertedpendulum-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}

  - run_id: reacher_random-search
    description: Random search – Reacher surrogate.
    dataset: {name: reacher-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: reacher_BOIL-linear
    description: BOIL linear – Reacher.
    dataset: {name: reacher-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: reacher_COCO-BOIL-M1-only
    description: COCO-BOIL M1 only – Reacher.
    dataset: {name: reacher-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: reacher_COCO-BOIL-M2-only
    description: COCO-BOIL M2 only – Reacher.
    dataset: {name: reacher-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}
  - run_id: reacher_COCO-BOIL-full
    description: COCO-BOIL full – Reacher.
    dataset: {name: reacher-v2, num_samples: 3000}
    model: {name: baseline_mlp, hidden_units: [64,64]}
    training: {epochs: 5, batch_size: 128, learning_rate: 0.001}

  # --------------------------------------------------------------------------------
  # END OF EXPERIMENT LIST ----------------------------------------------------------
  # --------------------------------------------------------------------------------

  # Note: The COCO-BOIL M1/M2/full logic at BO-level is provided by the
  # optimisation library *outside* the scope of this training script.  Here we
  # only need differentiated run-IDs and consistent meta-data so that the
  # orchestration layer can spawn the correct upstream HPO variation.
  # --------------------------------------------------------------------------------




































































































































































































































































































































































































































































































































































































































































